print("Top-level keys:", data.keys())

# Look for yield-related data
def find_yield_data(obj, path=""):
    if isinstance(obj, dict):
        for key, value in obj.items():
            if 'yield' in key.lower() or 'ay' in key.lower() or 'bond' in key.lower():
                print(f"{path}{key}: {type(value)}")
            find_yield_data(value, path + key + ".")
    elif isinstance(obj, list) and len(obj) > 0:
        find_yield_data(obj[0], path + "[0].")

# Try to find AY-1 or similar
if 'tables' in data:
    print("\nTables found:")
    for t in data['tables']:
        if isinstance(t, dict):
            print(f"  - {t.get('table_code', 'N/A')}: {t.get('title', 'N/A')[:50]}")
            if 'AY' in str(t.get('table_code', '')):
                print(f"    Found AY table!")
                print(f"    Keys: {t.keys()}")
